 void finishOnboarding(){introVisible=false;getIntent().removeExtra("show_onboarding");Store.prefs(this).edit().putBoolean("onboarded",true).apply();SyncJob.schedule(this);show("home");}
 class SlideActivateView extends View {
 final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float progress=0,startX;boolean dragging=false,completed=false;android.animation.ValueAnimator reset;
 SlideActivateView(Context c){super(c);setFocusable(true);setContentDescription("Активация радара. Протяните круг слева направо. Для экранного диктора используйте действие Увеличить.");setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
 float radius(){return getHeight()*.37f;}float left(){return getHeight()/2f;}float distance(){return Math.max(1,getWidth()-getHeight());}
 protected void onDraw(Canvas c){float h=getHeight(),r=radius(),cx=left()+distance()*progress,cy=h/2;
 p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,0,0,h,new int[]{Color.rgb(34,41,46),Color.rgb(9,12,15),Color.rgb(21,27,31)},null,Shader.TileMode.CLAMP));c.drawRoundRect(1,1,getWidth()-1,h-1,h/2,h/2,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(Color.rgb(65,77,86));c.drawRoundRect(1,1,getWidth()-1,h-1,h/2,h/2,p);
 p.setStyle(Paint.Style.FILL);p.setColor(CYAN);p.setAlpha((int)(progress*65));c.drawRoundRect(dp(5),dp(5),Math.max(h,cx+r),h-dp(5),h/2,h/2,p);p.setAlpha(255);
 p.setColor(MUTED);p.setTextSize(dp(14));p.setTextAlign(Paint.Align.CENTER);float tx=(getWidth()+h*.62f)/2;c.drawText("Проведи, чтобы начать",tx,cy-(p.ascent()+p.descent())/2,p);
 p.setShadowLayer(dp(9),0,dp(2),0x8058D5EE);p.setShader(new LinearGradient(0,cy-r,0,cy+r,Color.WHITE,Color.rgb(201,225,231),Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.clearShadowLayer();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2.5f));p.setColor(Color.rgb(14,29,36));Path arrow=new Path();arrow.moveTo(cx-dp(3),cy-dp(7));arrow.lineTo(cx+dp(4),cy);arrow.lineTo(cx-dp(3),cy+dp(7));c.drawPath(arrow,p);
 }
 public boolean onTouchEvent(android.view.MotionEvent e){if(completed)return true;switch(e.getActionMasked()){
 case MotionEvent.ACTION_DOWN:if(Math.hypot(e.getX()-(left()+distance()*progress),e.getY()-getHeight()/2f)>radius()+dp(10))return false;if(reset!=null)reset.cancel();startX=e.getX()-progress*distance();dragging=true;getParent().requestDisallowInterceptTouchEvent(true);return true;
 case MotionEvent.ACTION_MOVE:if(!dragging)return false;progress=Math.max(0,Math.min(1,(e.getX()-startX)/distance()));invalidate();return true;
 case MotionEvent.ACTION_UP:if(!dragging)return false;dragging=false;getParent().requestDisallowInterceptTouchEvent(false);if(progress>=.92f)activate();else resetProgress();return true;
 case MotionEvent.ACTION_CANCEL:dragging=false;resetProgress();return true;default:return true;}}
 void resetProgress(){reset=android.animation.ValueAnimator.ofFloat(progress,0);reset.setDuration(220);reset.addUpdateListener(a->{progress=(float)a.getAnimatedValue();invalidate();});reset.start();}
 void activate(){if(completed)return;completed=true;progress=1;invalidate();performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);announceForAccessibility("Радар активирован");finishOnboarding();}
 @Override public void onInitializeAccessibilityNodeInfo(android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.setClassName(SeekBar.class.getName());info.setRangeInfo(android.view.accessibility.AccessibilityNodeInfo.RangeInfo.obtain(android.view.accessibility.AccessibilityNodeInfo.RangeInfo.RANGE_TYPE_INT,0,100,progress*100));info.addAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);}
 @Override public boolean performAccessibilityAction(int action,Bundle args){if(action==android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_FORWARD){progress=Math.min(1,progress+.25f);if(progress>=1)activate();else{invalidate();announceForAccessibility((int)(progress*100)+" процентов");}return true;}if(action==android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD){progress=Math.max(0,progress-.25f);invalidate();return true;}return super.performAccessibilityAction(action,args);}
 @Override public boolean onKeyDown(int code,android.view.KeyEvent e){if(code==KeyEvent.KEYCODE_DPAD_RIGHT)return performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null);if(code==KeyEvent.KEYCODE_DPAD_LEFT)return performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD,null);return super.onKeyDown(code,e);}
 @Override protected void onDetachedFromWindow(){if(reset!=null)reset.cancel();super.onDetachedFromWindow();}
 }
